"""Generate oath data and ja/en/ru text. Use --check to verify the generated files."""
from __future__ import annotations
import argparse
import json
import xml.etree.ElementTree as ET
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
MOD = ROOT / 'poc/JAC_PoC_SengokuTrees'
SOURCE = ROOT / 'documents/poc/data/sengoku-oaths.json'
LANGUAGES = ('ja_JP', 'en_US', 'ru_RU')
AGES = ('NORMAL', 'DARK', 'GOLDEN', 'HEROIC')
YIELDS = {
    'production': ('YIELD_PRODUCTION', '生産', 'Production', 'производство'),
    'gold': ('YIELD_GOLD', 'ゴールド', 'Gold', 'золото'),
    'science': ('YIELD_SCIENCE', '科学', 'Science', 'наука'),
    'culture': ('YIELD_CULTURE', '文化', 'Culture', 'культура'),
    'faith': ('YIELD_FAITH', '信仰', 'Faith', 'вера'),
    'food': ('YIELD_FOOD', '食料', 'Food', 'пища'),
}
LABELS = {
    'military': ('軍事ユニットの生産', 'military unit Production', 'производство военных юнитов'),
    'naval': ('水軍の生産', 'naval unit Production', 'производство морских юнитов'),
    'growth': ('人口成長', 'population growth', 'рост населения'),
    'walls': ('防壁の生産', 'wall Production', 'производство стен'),
}
QUESTS = {
    'CAPTURE': ('他家の城を占領するごとに', "Each capture of another house's city", 'Каждый захват города другого дома'),
    'TECH': ('技術を完了するごとに', 'Each technology completed', 'Каждое завершённое исследование технологии'),
    'CIVIC': ('社会制度を完了するごとに', 'Each civic completed', 'Каждый завершённый общественный институт'),
    'RELATION': ('新たな同盟・友好宣言を結ぶごとに（開始時の関係は除外、同じ組・同種は1期1回）', 'Each new alliance or declared friendship (starting relations excluded; once per pair and kind per reign)', 'Каждый новый союз или объявленная дружба (начальные отношения исключены; раз на пару и вид за эпоху)'),
}
UI_TEXT = {
    'TITLE': ('誓約 — {1_Name}', 'Oaths — {1_Name}', 'Обеты — {1_Name}'),
    'AGE': ('{1_Age}：{2_Count}つ選ぶ', '{1_Age}: choose {2_Count}', '{1_Age}: выберите {2_Count}'),
    'PENDING': ('次の手番までに誓約を選ぶ。未選択なら自動で決定。', 'Choose an oath before the next turn; otherwise a choice is made automatically.', 'Выберите обет до следующего хода, иначе он будет выбран автоматически.'),
    'CHOOSE': ('誓約を選ぶ', 'Choose oaths', 'Выбрать обеты'),
    'ACTIVE': ('誓約：{1_Names}', 'Oaths: {1_Names}', 'Обеты: {1_Names}'),
    'SCORE': ('誓約の達成：{1_Points}点', 'Oath achievements: {1_Points} points', 'Выполнение обетов: {1_Points} очк.'),
}


def catalogue():
    return json.loads(SOURCE.read_text(encoding='utf-8'))['houses']


def effect_text(oath, lang):
    parts = [f"{YIELDS[k][lang+1] if k in YIELDS else LABELS[k][lang]} +{n}%" for k, n in oath['effects']]
    return ('全都市：', 'All cities: ', 'Все города: ')[lang] + ('、' if lang == 0 else ', ').join(parts) + ('。次の改元まで。', '. Until the next era-name change.', '. До следующей смены эпохи.')[lang]


def quest_text(oath, lang):
    return QUESTS[oath['quest']][lang] + ('、武功の台帳に +1点。', ': +1 point in the deeds ledger.', ': +1 очко в реестре заслуг.')[lang]


def sql_text():
    out = '''-- Generated by tools/generate_sengoku_oaths.py. Balance is provisional.
-- Only RULESET_JAC_BANSEIKI. References: documents/poc/sengoku-oaths.md.
-- Clear FK links before deleting official choices, preserving historic timeline moments
-- (Expansion2_Schema.sql:80-102,489). No shared oath for unlisted civilizations.
UPDATE Moments SET CommemorationType=NULL;
UPDATE DiplomaticActions_XP1 SET RequiresGoldenAgeCommemorationType=NULL;
DELETE FROM AiFavoredItems WHERE Item IN (SELECT CommemorationType FROM CommemorationTypes);
DELETE FROM CommemorationModifiers;
DELETE FROM ComplimentModifiers;
DELETE FROM CommemorationTypes;

-- No Civilization FK: the optional CustomCivs sibling may load later.
CREATE TABLE JAC_SengokuOaths (
  OathType TEXT NOT NULL PRIMARY KEY CHECK (OathType LIKE 'JAC_OATH_%'),
  CivilizationType TEXT NOT NULL,
  Position INTEGER NOT NULL CHECK (Position BETWEEN 1 AND 3),
  Name TEXT NOT NULL, GoldenDescription TEXT NOT NULL, QuestDescription TEXT NOT NULL,
  Icon TEXT NOT NULL,
  QuestType TEXT NOT NULL CHECK (QuestType IN ('CAPTURE','TECH','CIVIC','RELATION')),
  AIFocus TEXT NOT NULL CHECK (AIFocus IN ('WAR','ECONOMY','LEARNING','GROWTH','NAVAL','FAITH')),
  UNIQUE (CivilizationType, Position)
);
CREATE TABLE JAC_SengokuOathAges (
  OathType TEXT NOT NULL REFERENCES JAC_SengokuOaths (OathType),
  AgeType TEXT NOT NULL CHECK (AgeType IN ('NORMAL','DARK','GOLDEN','HEROIC')),
  PRIMARY KEY (OathType, AgeType)
);
CREATE TABLE JAC_SengokuOathEffects (
  OathType TEXT NOT NULL REFERENCES JAC_SengokuOaths (OathType),
  ModifierId TEXT NOT NULL REFERENCES Modifiers (ModifierId),
  PRIMARY KEY (OathType, ModifierId)
);
'''
    rows = {}
    def add(table, columns, *values):
        if table not in rows:
            rows[table] = (columns, [])
        rows[table][1].append(values)
    def modifier(key, kind, owner=None, subject=None):
        add('Modifiers', 'ModifierId, ModifierType, OwnerRequirementSetId, SubjectRequirementSetId', key, kind, owner, subject)
    def argument(key, name, value):
        add('ModifierArguments', 'ModifierId, Name, Value', key, name, value)
    def attach(oath, key):
        add('TraitModifiers', 'TraitType, ModifierId', 'TRAIT_LEADER_MAJOR_CIV', key)
        add('JAC_SengokuOathEffects', 'OathType, ModifierId', oath, key)
    for house in catalogue():
        for position, oath in enumerate(house['oaths'], 1):
            key = 'JAC_OATH_' + house['id'] + '_' + oath['id']
            tag = 'LOC_' + key
            icon = {'WAR':'MILITARY','NAVAL':'EXPLORATION','ECONOMY':'ECONOMIC','LEARNING':'SCIENTIFIC','GROWTH':'INFRASTRUCTURE','FAITH':'RELIGIOUS'}[oath['focus']]
            add('JAC_SengokuOaths', 'OathType, CivilizationType, Position, Name, GoldenDescription, QuestDescription, Icon, QuestType, AIFocus', key, 'CIVILIZATION_JAC_'+house['id'], position, tag+'_NAME', tag+'_GOLDEN', tag+'_QUEST', 'ICON_COMMEMORATION_'+icon, oath['quest'], oath['focus'])
            for age in AGES:
                add('JAC_SengokuOathAges', 'OathType, AgeType', key, age)
            req, gate = key+'_REQ', key+'_CITY'
            add('Requirements', 'RequirementId, RequirementType', req, 'REQUIREMENT_PLOT_PROPERTY_MATCHES')
            add('RequirementArguments', 'RequirementId, Name, Value', req, 'PropertyName', key+'_ON')
            add('RequirementArguments', 'RequirementId, Name, Value', req, 'PropertyMinimum', 1)
            add('RequirementSets', 'RequirementSetId, RequirementSetType', gate, 'REQUIREMENTSET_TEST_ALL')
            add('RequirementSetRequirements', 'RequirementSetId, RequirementId', gate, req)
            for index, (kind, amount) in enumerate(oath['effects'], 1):
                mid = key+'_E'+str(index)
                if kind in YIELDS:
                    modifier(mid, 'MODIFIER_PLAYER_CITIES_ADJUST_CITY_YIELD_MODIFIER', subject=gate)
                    argument(mid, 'YieldType', YIELDS[kind][0])
                elif kind == 'military':
                    modifier(mid, 'MODIFIER_PLAYER_CITIES_ADJUST_MILITARY_UNITS_PRODUCTION', subject=gate)
                elif kind == 'growth':
                    modifier(mid, 'MODIFIER_PLAYER_CITIES_ADJUST_CITY_GROWTH', subject=gate)
                elif kind == 'walls':
                    for tier, building in (('ANCIENT','BUILDING_WALLS'),('MEDIEVAL','BUILDING_CASTLE'),
                                           ('RENAISSANCE','BUILDING_STAR_FORT')):
                        wid = mid+'_'+tier
                        modifier(wid, 'MODIFIER_PLAYER_CITIES_ADJUST_BUILDING_PRODUCTION', subject=gate)
                        argument(wid, 'BuildingType', building)
                        argument(wid, 'Amount', amount)
                        attach(key, wid)
                    continue
                elif kind == 'naval':
                    aid = mid+'_ATTACH'
                    modifier(aid, 'MODIFIER_PLAYER_CITIES_ATTACH_MODIFIER')
                    argument(aid, 'ModifierId', mid)
                    modifier(mid, 'MODIFIER_CITY_ADJUST_UNIT_DOMAIN_PRODUCTION', owner=gate)
                    argument(mid, 'Domain', 'DOMAIN_SEA')
                    attach(key, aid)
                    add('JAC_SengokuOathEffects', 'OathType, ModifierId', key, mid)
                else:
                    raise ValueError(kind)
                argument(mid, 'Amount', amount)
                if kind != 'naval':
                    attach(key, mid)
    # FK-dependent effect mappings must come after Modifiers, even though collected interleaved.
    columns, values = rows.pop('JAC_SengokuOathEffects')
    rows['JAC_SengokuOathEffects'] = (columns, values)
    def quote(v):
        return 'NULL' if v is None else "'" + str(v).replace("'", "''") + "'"
    for table, (columns, values) in rows.items():
        out += f'\nINSERT INTO {table} ({columns}) VALUES\n' + ',\n'.join('  ('+', '.join(map(quote,v))+')' for v in values) + ';\n'
    return out


def text_xml():
    root = ET.Element('GameData')
    root.append(ET.Comment(' Generated by tools/generate_sengoku_oaths.py. '))
    table = ET.SubElement(root, 'LocalizedText')
    texts = {'LOC_JAC_OATH_'+k:v for k,v in UI_TEXT.items()}
    for house in catalogue():
        for oath in house['oaths']:
            key = 'LOC_JAC_OATH_'+house['id']+'_'+oath['id']
            texts[key+'_NAME'] = oath['names']
            texts[key+'_GOLDEN'] = [effect_text(oath,i) for i in range(3)]
            texts[key+'_QUEST'] = [quest_text(oath,i) for i in range(3)]
    for key, values in texts.items():
        for lang, value in zip(LANGUAGES, values):
            row = ET.SubElement(table, 'Row', Tag=key, Language=lang)
            ET.SubElement(row, 'Text').text = value
    ET.indent(root, space='\t')
    return '<?xml version="1.0" encoding="utf-8"?>\n' + ET.tostring(root, encoding='unicode') + '\n'


def outputs():
    return {MOD/'Data/JAC_Sengoku_Oaths.sql':sql_text(), MOD/'Text/JAC_Sengoku_Oaths_Text.xml':text_xml()}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    for path, text in outputs().items():
        if args.check:
            if not path.is_file() or path.read_text(encoding='utf-8') != text:
                parser.exit(1, f'Stale oath artifact: {path.relative_to(ROOT)}\n')
        else:
            path.write_text(text, encoding='utf-8', newline='\n')
    print('oaths: 22 houses, 66 choices; '+('up to date' if args.check else 'generated'))


if __name__ == '__main__':
    main()
